PRAGMA foreign_keys=ON;
CREATE TABLE documents(id TEXT PRIMARY KEY,root_id TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL CHECK(status IN('draft','review','approved','issued')),kind TEXT NOT NULL CHECK(kind IN('proposal','tender-response','rfq','capability')),title TEXT NOT NULL,client_name TEXT NOT NULL DEFAULT '',reference TEXT NOT NULL DEFAULT '',data_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,created_by TEXT NOT NULL,updated_by TEXT NOT NULL,approved_by TEXT,approved_at TEXT,issued_at TEXT,pdf_key TEXT,pdf_sha256 TEXT,UNIQUE(root_id,revision));
CREATE INDEX documents_updated_idx ON documents(updated_at DESC);CREATE INDEX documents_root_idx ON documents(root_id,revision DESC);
CREATE TABLE attachments(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,r2_key TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL);CREATE INDEX attachments_document_idx ON attachments(document_id);
CREATE TABLE audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,document_id TEXT,actor TEXT NOT NULL,action TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
